                super.getModelResource(renderState);
    }

    @Override
    public ResourceLocation getTextureResource(GeoRenderState renderState) {
        return renderState.getOrDefaultGeckolibData(IS_BABY_DATA_TICKET, Boolean.FALSE) ? this.babyTexturePath :
                super.getTextureResource(renderState);
    }

    @Override
    public ResourceLocation getAnimationResource(T animatable) {
        return animatable.isBaby() ? this.babyAnimationsPath : super.getAnimationResource(animatable);
